<?php require_once 'auth.php'; requireAdmin();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$email=trim($_POST['email']);$password=$_POST['password'];$role=$_POST['role'];if(!in_array($role,['Admin','Editor'])){$role='Editor';}$hash=password_hash($password,PASSWORD_DEFAULT);try{$stmt=$pdo->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)');$stmt->execute([$name,$email,$hash,$role]);header('Location: users.php');exit;}catch(PDOException $e){$error='الإيميل مستخدم مسبقاً';}}
require_once 'header.php'; ?>
<div class="admin-layout"><?php require_once 'sidebar.php'; ?><main class="admin-content"><h1>إضافة مستخدم</h1><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form method="POST" class="card"><input class="form-control" name="name" placeholder="الاسم" required><input class="form-control" type="email" name="email" placeholder="الإيميل" required><input class="form-control" type="password" name="password" placeholder="كلمة المرور" required><select class="form-control" name="role"><option value="Editor">Editor</option><option value="Admin">Admin</option></select><button class="btn">حفظ</button></form></main></div></body></html>
